import{_ as t,o as a,c as s,a2 as n}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"Networking","description":"","frontmatter":{},"headers":[],"relativePath":"manual/network.md","filePath":"manual/network.md"}'),o={name:"manual/network.md"};function r(i,e,d,c,l,h){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="networking" tabindex="-1">Networking <a class="header-anchor" href="#networking" aria-label="Permalink to &quot;Networking&quot;">​</a></h1><p>A self-contained TCP/IP stack with everything from NIC drivers to an SSH server - no ported libc, no third-party code.</p><h2 id="bring-up" tabindex="-1">Bring-up <a class="header-anchor" href="#bring-up" aria-label="Permalink to &quot;Bring-up&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; dhcp                  (request an address on nic0)</span></span>
<span class="line"><span>oc&gt; ping 10.0.2.2         (ICMP echo to the QEMU gateway)</span></span>
<span class="line"><span>oc&gt; dns example.com       (resolve via the QEMU DNS forwarder)</span></span>
<span class="line"><span>oc&gt; wget 10.0.2.2         (fetch http://10.0.2.2/)</span></span>
<span class="line"><span>oc&gt; wget host 8080 /path  (explicit port and path)</span></span>
<span class="line"><span>oc&gt; route                 (routing table)</span></span>
<span class="line"><span>oc&gt; tcpstats              (TCP counters + congestion state)</span></span>
<span class="line"><span>oc&gt; firewall              (stateful firewall rules)</span></span></code></pre></div><p>In QEMU the default <code>-device e1000</code> matches the e1000 driver out of the box:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>qemu-system-x86_64 -m 512 -cdrom opencube.iso \\</span></span>
<span class="line"><span>    -netdev user,id=n1 -device e1000,netdev=n1</span></span></code></pre></div><h2 id="supported-nics" tabindex="-1">Supported NICs <a class="header-anchor" href="#supported-nics" aria-label="Permalink to &quot;Supported NICs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Family</th><th>Cards</th><th>Driver</th></tr></thead><tbody><tr><td>Intel e1000</td><td>e1000 (8254x)</td><td><code>drivers/nic/driver_nic.c</code></td></tr><tr><td>Intel e1000e</td><td>8257x ICH/PCH NICs</td><td><code>driver_nic_e1000e.c</code></td></tr><tr><td>Intel igb</td><td>82575/82576 (VFs included)</td><td><code>driver_nic_igb.c</code></td></tr><tr><td>Intel ixgbe</td><td>82598/82599 10 GbE</td><td><code>driver_nic_ixgbe.c</code></td></tr><tr><td>Realtek rtl8139</td><td>8139/810x fast ethernet</td><td><code>driver_nic_rtl8139.c</code></td></tr><tr><td>Realtek rtl8169</td><td>8168/8125/810x gigabit families</td><td><code>driver_nic_rtl8169.c</code></td></tr><tr><td>Broadcom BCM57xx</td><td>5708/5709/5714 era</td><td><code>driver_nic_bcm57xx.c</code></td></tr></tbody></table><h2 id="the-stack" tabindex="-1">The stack <a class="header-anchor" href="#the-stack" aria-label="Permalink to &quot;The stack&quot;">​</a></h2><p>ARP, IPv4, ICMP, UDP, DNS, TCP with congestion control (<code>net_tcp_cc.c</code>), a socket API for user programs, and a stateful firewall. Every layer is visible through commands: <code>arp</code>, <code>route</code>, <code>tcpstats</code>, <code>firewall</code>, <code>nicstat</code>.</p><h2 id="https-client-tls-1-2-1-3" tabindex="-1">HTTPS client (TLS 1.2 / 1.3) <a class="header-anchor" href="#https-client-tls-1-2-1-3" aria-label="Permalink to &quot;HTTPS client (TLS 1.2 / 1.3)&quot;">​</a></h2><p><code>wget https://...</code> negotiates TLS with RSA and ECDHE key exchange, verifies X.509 chains (RFC 6125 hostname policy - IP-literal URLs have no reference identity), and rejects tampered certificates. The crypto core (AES, SHA-2 family, HMAC, RSA, NIST curves, Ed25519-style primitives) is the same code <code>cryptotest</code> validates with NIST vectors.</p><p>DH key exchange correctness and timing: <code>dhtest</code>.</p><h2 id="ssh-client-and-server" tabindex="-1">SSH: client and server <a class="header-anchor" href="#ssh-client-and-server" aria-label="Permalink to &quot;SSH: client and server&quot;">​</a></h2><ul><li><p><strong>Client</strong> (<code>ssh</code> command): connect, authenticate, run a remote command - key exchange via curve25519-style primitives.</p></li><li><p><strong>Server</strong> (<code>sshd</code>): a real SSH server <em>inside the guest</em>. Host and client keys live on the /etc volume (<code>host_keygen_etc</code> seeds them); authorized keys are managed there too. From your host:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ssh -p &lt;port&gt; root@localhost     (forward a QEMU port to try it)</span></span></code></pre></div><p>The E2E suite exercises a full paramiko login round-trip against the in-guest sshd.</p></li></ul><h2 id="dns" tabindex="-1">DNS <a class="header-anchor" href="#dns" aria-label="Permalink to &quot;DNS&quot;">​</a></h2><p><code>dns &lt;name&gt;</code> resolves through the configured resolver (QEMU&#39;s user-mode stack forwards to the host). Cached entries are visible through the network stats commands.</p><h2 id="what-is-not-there-honest-list" tabindex="-1">What is not there (honest list) <a class="header-anchor" href="#what-is-not-there-honest-list" aria-label="Permalink to &quot;What is not there (honest list)&quot;">​</a></h2><ul><li>IPv6 is not implemented.</li><li>Wi-Fi association: the wireless stack (<code>wifi</code> command) covers status/scan/test across the ath/brcm/iwlwifi/rtlwifi families and the SDIO bus - full association on real hardware depends on the card family; in QEMU there is no Wi-Fi device model to attach.</li><li>NAT traversal/port forwarding are QEMU user-mode properties, not kernel features.</li></ul>`,19)])])}const g=t(o,[["render",r]]);export{u as __pageData,g as default};
